import{d as g,C as n,o as d,c as h,E as i,a3 as a}from"./chunks/framework.D4-ViStF.js";const x=JSON.parse('{"title":"恒卦","description":"雷风恒，震 ☳ 巽 ☴","frontmatter":{"title":"恒卦","description":"雷风恒，震 ☳ 巽 ☴","category":"hexagram","aliases":["恒","雷风恒"],"source":["《周易》"]},"headers":[],"relativePath":"yijing/hexagrams/hexagram-32.md","filePath":"yijing/hexagrams/hexagram-32.md","lastUpdated":1788516578000}'),p={name:"yijing/hexagrams/hexagram-32.md"},y=g({...p,setup(m){const o=[{id:"heng",term:"恒",pinyin:"héng",meaning:"长久、持久。恒卦之名。",context:"恒不是死守不变，而是持久地合道。"},{id:"jun",term:"浚",pinyin:"jùn",meaning:"深挖、疏浚。「浚恒」一上来就求深，根基未稳而急于见底。"},{id:"zhen",term:"贞",sense:1},{id:"huiwang",term:"悔亡"},{id:"buhengqide",term:"不恒其德",pinyin:"bù héng qí dé",meaning:"德行不能长久保持，今日一个样、明日一个样。"},{id:"chengzhixiu",term:"承之羞",pinyin:"chéng zhī xiū",meaning:"承受羞辱。「或承之羞」即或许就要蒙羞。"},{id:"tianwuqin",term:"田无禽",pinyin:"tián wú qín",meaning:"田猎一无所获。喻方向错了、劳而无功。"},{id:"zhenheng",term:"振恒",pinyin:"zhèn héng",meaning:"动荡不休地维持「恒」，靠用力振动撑着的恒。"},{id:"liyiyifang",term:"立不易方",pinyin:"lì bù yì fāng",meaning:"立身而不改易方向与原则。方即方向与方正。"},{id:"jiuyuqidao",term:"久于其道",pinyin:"jiǔ yú qí dào",meaning:"长久地守住正道。",context:"彖传反复点明：恒之所以亨，在于久于其道。"},{id:"xun",term:"巽",pinyin:"xùn",meaning:"顺入、谦逊；亦指巽卦之风，无孔不入。"},{id:"congyierzhong",term:"从一而终",pinyin:"cóng yī ér zhōng",meaning:"跟随一个而到底，坚守不渝。"},{id:"zhiyi",term:"制义",pinyin:"zhì yì",meaning:"以义权衡、裁断，不固执己见。"},{id:"wuyouli",term:"无攸利"}],e=[{position:"初六",type:"yin",text:"浚恒，贞凶，无攸利。",xiang:"浚恒之凶，始求深也。",textModern:"根基未稳就一味求深，守正也会凶，没有任何好处。",xiangModern:"浚恒之所以凶，是因为一开始就求深，把根基逼到极限。"},{position:"九二",type:"yang",text:"悔亡。",xiang:"九二悔亡，能久中也。",textModern:"悔恨消失。",xiangModern:"九二悔恨消失，是因为能长久地守持中道。"},{position:"九三",type:"yang",text:"不恒其德，或承之羞，贞吝。",xiang:"不恒其德，无所容也。",textModern:"德行不能长久保持，或许会承受羞辱；即使自以为守正，也难免憾惜。",xiangModern:"德行不恒的人，天地无所容纳、人心无所依凭。"},{position:"九四",type:"yang",text:"田无禽。",xiang:"久非其位，安得禽也。",textModern:"田猎却一无所获。",xiangModern:"长久地待在不该待的位置，怎么可能猎到禽兽呢。"},{position:"六五",type:"yin",text:"恒其德，贞。妇人吉，夫子凶。",xiang:"妇人贞吉，从一而终也。夫子制义，从妇凶也。",textModern:"恒守其德、守正不移：妇人如此则吉，男子如此则凶。",xiangModern:"妇人守正则吉，因其从一而终；男子当以义制事，若一味顺从守旧则凶。"},{position:"上六",type:"yin",text:"振恒，凶。",xiang:"振恒在上，大无功也。",textModern:"动荡不休地维持「恒」，凶。",xiangModern:"居卦之终却动荡不止，终究徒劳无功。"}];return(u,t)=>{const r=n("DaoHexagramViewer"),l=n("DaoHexagramYaoCards"),s=n("DaoKeywordCards");return d(),h("div",null,[i(r,{name:"恒",fullName:"雷风恒",upper:"☳",lower:"☴",guaCi:"恒，亨，无咎，利贞，利有攸往。",pinyin:["héng"],element:"木",direction:"东",insight:"雷动风行，恒久不已；恒不是死守，是在正确的方向上守、动、止。",guaSlug:"32leifengheng",lines:e}),t[0]||(t[0]=a('<h2 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to &quot;象传&quot;">​</a></h2><p>雷风，恒。君子以立不易方。</p><p>雷与风相伴相生、相互激荡，一刻不停，这就是恒；君子由此领悟：立身处世，要立定一个方向、守住一条原则，不因风雨而改易。</p><p>「立不易方」——<strong>立</strong>是立身、立定；<strong>不易</strong>是不改变；<strong>方</strong>是方向、方正。合起来：立身而不改易方向与原则。方是「方向 + 原则」：方向错了，越恒越远；原则丢了，越恒越飘。所以恒的前提，是先立好这个「方」。</p><p>分形结构：</p><ul><li>雷（动）→ 变中之恒：雷霆万钧，方向始终如一</li><li>风（入）→ 恒中之变：风无孔不入，顺势而进</li></ul><p>雷与风一动一入，看似相反，却恒久相伴——真正的恒不是纹丝不动，而是在变化中守住不变的那个「方」。</p><h2 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to &quot;彖传&quot;">​</a></h2><p>恒，久也。刚上而柔下，雷风相与，巽而动，刚柔皆应，恒。恒亨无咎利贞，久于其道也。天地之道，恒久而不已也。利有攸往，终则有始也。日月得天而能久照，四时变化而能久成，圣人久于其道而天下化成。观其所恒，而天地万物之情可见矣。</p><p>逐句释义：</p><ul><li><strong>恒，久也</strong> —— 恒的本义就是长久、持久。</li><li><strong>刚上而柔下，雷风相与，巽而动，刚柔皆应</strong> —— 刚（震）上、柔（巽）下，各得其位；雷风相互激荡；顺入（巽）而动（震）；上下刚柔全部相应。这样的结构，才配得上「恒」。</li><li><strong>恒亨无咎利贞，久于其道也</strong> —— 恒之所以亨通、无咎、利于守正，是因为长久地守住正道。</li><li><strong>天地之道，恒久而不已也</strong> —— 天地的运行之道，是恒久而不停息的。</li><li><strong>利有攸往，终则有始也</strong> —— 所以利于前往：终点之后，自有新的开始。</li><li><strong>日月得天而能久照，四时变化而能久成</strong> —— 日月循天而行，才能长久照耀；四时更迭变化，才能长久成就万物。</li><li><strong>圣人久于其道而天下化成</strong> —— 圣人长久地坚守正道，天下才教化有成。</li><li><strong>观其所恒，而天地万物之情可见矣</strong> —— 看它们恒守的是什么，天地万物的真实性情便一目了然。</li></ul><blockquote><p><strong>恒的悖论</strong>：日月、四时无不在变，却因各循其道而显得「恒」。真正的恒不是不变，而是在变化中守住不变的道。</p></blockquote><h2 id="六爻" tabindex="-1">六爻 <a class="header-anchor" href="#六爻" aria-label="Permalink to &quot;六爻&quot;">​</a></h2>',13)),i(l,{element:"木",guaSlug:"32leifengheng",glossary:o,items:e}),t[1]||(t[1]=a('<h2 id="六爻详解" tabindex="-1">六爻详解 <a class="header-anchor" href="#六爻详解" aria-label="Permalink to &quot;六爻详解&quot;">​</a></h2><h3 id="初六-·-浚恒-贞凶-无攸利" tabindex="-1">初六 · 浚恒，贞凶，无攸利 <a class="header-anchor" href="#初六-·-浚恒-贞凶-无攸利" aria-label="Permalink to &quot;初六 · 浚恒，贞凶，无攸利&quot;">​</a></h3><ul><li><strong>浚</strong> → 深挖、疏浚</li><li><strong>浚恒</strong> → 一开始就追求「深」的恒，根基未稳便向下猛挖</li><li><strong>贞凶</strong> → 即使守正，也凶（方向对、方式错）</li><li><strong>无攸利</strong> → 没有任何好处</li></ul><p>象曰「浚恒之凶，始求深也」——凶，恰恰凶在「始求深」。</p><p>初六阴爻居卦之始，位卑力微、根基尚浅。此时的「恒」，不该是深挖，而该是固根。一段关系、一份事业、一个新身份刚起步，就急着把「恒」做给别人看——誓约、承诺、捆绑——正是浚恒。</p><blockquote><p>核心洞见：恒是长出来的，不是挖出来的。根基未稳时的「坚持」，往往不是坚定，是恐惧。</p></blockquote><h3 id="九二-·-悔亡" tabindex="-1">九二 · 悔亡 <a class="header-anchor" href="#九二-·-悔亡" aria-label="Permalink to &quot;九二 · 悔亡&quot;">​</a></h3><p>全卦唯一一个「悔亡」——没有铺垫，直接给结果。象曰「能久中也」：阳爻居柔位（得中而不过刚），知道何时该守、何时该动，守得住中道。</p><p>「悔亡」不是从来没有悔，而是悔生即化：察觉偏了，立刻回来。真正恒久的人，靠的不是从不犯错，而是纠错快。</p><blockquote><p>悔亡三要件：知道什么该恒（方向）、恒在点子上（中道）、错了能回来（不执）。</p></blockquote><h3 id="九三-·-不恒其德-或承之羞-贞吝" tabindex="-1">九三 · 不恒其德，或承之羞，贞吝 <a class="header-anchor" href="#九三-·-不恒其德-或承之羞-贞吝" aria-label="Permalink to &quot;九三 · 不恒其德，或承之羞，贞吝&quot;">​</a></h3><ul><li><strong>不恒其德</strong> → 德行不能长久保持，今天一个样、明天一个样</li><li><strong>或承之羞</strong> → 或许就要承受羞辱</li><li><strong>贞吝</strong> → 即使自以为守正，也难免憾惜</li></ul><p>象曰「不恒其德，无所容也」——德行不恒的人，天地无所容、人心无所依。</p><p>九三阳居阳位，过刚而躁，下无应。它的「不恒」不是没志气，而是太想表现自己，反而守不住。写作、修行、关系中最常见的也是九三：三天打鱼、两天晒网，一曝十寒。</p><blockquote><p>恒德的试金石：无人看见时，你怎么选。人前恒易，人后恒难。</p></blockquote><h3 id="九四-·-田无禽" tabindex="-1">九四 · 田无禽 <a class="header-anchor" href="#九四-·-田无禽" aria-label="Permalink to &quot;九四 · 田无禽&quot;">​</a></h3><ul><li><strong>田</strong> → 田猎</li><li><strong>田无禽</strong> → 打了一天猎，一无所获</li></ul><p>象曰「久非其位，安得禽也」——长久地待在不该待的位置，怎么可能有收获。</p><p>九四阳爻居阴位，不得位、又无应。它的「恒」用错了地方：方向错了，坚持得越久，空转得越久。九二守恒于中，悔亡；九四恒于非位，无禽——同样是「恒」，一个化悔，一个空转。</p><blockquote><p>核心逻辑：恒的前提是方向对。方向错的坚持不叫恒，叫固执；方向对的放弃不叫放弃，叫止损。</p></blockquote><h3 id="六五-·-恒其德-贞。妇人吉-夫子凶" tabindex="-1">六五 · 恒其德，贞。妇人吉，夫子凶 <a class="header-anchor" href="#六五-·-恒其德-贞。妇人吉-夫子凶" aria-label="Permalink to &quot;六五 · 恒其德，贞。妇人吉，夫子凶&quot;">​</a></h3><ul><li><strong>恒其德，贞</strong> → 恒守其德、守正不移</li><li><strong>妇人吉，夫子凶</strong> → 妇人如此则吉，男子如此则凶</li></ul><p>象曰「妇人贞吉，从一而终也。夫子制义，从妇凶也」——妇人以从一而终为吉；男子当以义制事、权衡裁断，若一味从守，则凶。</p><p>六五阴爻居君位（得中而不得位），是恒卦中的「君」，象征着权力与责任。六五的警示是：<strong>君位上的恒，是「制义」，不是「从一」</strong>。真守，是看清全局后的坚守；以守逃避，是拿「恒」当挡箭牌，回避本该做的决断。</p><blockquote><p>君位之辩：真守 vs 以守逃避。真守——知道为什么守、守到什么为止；以守逃避——把「恒」当成不做决定的理由。妇人吉、夫子凶：弱者的守是一种成全，强者的守是一种失职。</p></blockquote><h3 id="上六-·-振恒-凶" tabindex="-1">上六 · 振恒，凶 <a class="header-anchor" href="#上六-·-振恒-凶" aria-label="Permalink to &quot;上六 · 振恒，凶&quot;">​</a></h3><ul><li><strong>振恒</strong> → 动荡不休地维持「恒」，靠用力振动撑着的恒</li><li><strong>凶</strong></li></ul><p>象曰「振恒在上，大无功也」——居卦之终却动荡不止，终究徒劳无功。</p><p>上六阴爻居卦之终，该收的时候不收，反而越振越急。恒到极点反而躁动：该止不止、该退不退，把「恒」透支成惯性，把坚持熬成执念。</p><blockquote><p>知止：恒的终点，是知道何时止。知道何时止的人，恒才有善终；不知止的人，恒只是慢性消耗。</p></blockquote><h2 id="【原典层】字词释义" tabindex="-1">【原典层】字词释义 <a class="header-anchor" href="#【原典层】字词释义" aria-label="Permalink to &quot;【原典层】字词释义&quot;">​</a></h2>',31)),i(s,{title:"字词释义",items:[{term:"恒",pinyin:["héng"],meaning:"长久、持久。恒不是死守不变，而是持久地合道。"},{term:"浚",pinyin:["jùn"],meaning:"深挖、疏浚。「浚恒」一上来就求深，根基未稳而急于见底。"},{term:"贞",sense:1},{term:"悔亡"},{term:"不恒其德",pinyin:["bù","héng","qí","dé"],meaning:"德行不能长久保持，今日一个样、明日一个样。"},{term:"承之羞",pinyin:["chéng","zhī","xiū"],meaning:"承受羞辱。「或承之羞」即或许就要蒙羞。"},{term:"田无禽",pinyin:["tián","wú","qín"],meaning:"田猎一无所获。喻方向错了、劳而无功。"},{term:"振恒",pinyin:["zhèn","héng"],meaning:"动荡不休地维持「恒」，靠用力振动撑着的恒。"},{term:"立不易方",pinyin:["lì","bù","yì","fāng"],meaning:"立身而不改易方向与原则。方即方向与方正。"},{term:"久于其道",pinyin:["jiǔ","yú","qí","dào"],meaning:"长久地守住正道。恒之所以亨，在于久于其道。"},{term:"巽",pinyin:["xùn"],meaning:"顺入、谦逊；亦指巽卦之风，无孔不入。"},{term:"从一而终",pinyin:["cóng","yī","ér","zhōng"],meaning:"跟随一个而到底，坚守不渝。"},{term:"制义",pinyin:["zhì","yì"],meaning:"以义权衡、裁断，不固执己见。"},{term:"无攸利"}]}),t[2]||(t[2]=a('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一卦在说什么" tabindex="-1">象：这一卦在说什么 <a class="header-anchor" href="#象-这一卦在说什么" aria-label="Permalink to &quot;象：这一卦在说什么&quot;">​</a></h3><p>恒卦讲的是<strong>持久之道</strong>。上震（雷、动）压下巽（风、入），雷动风行、相互激荡，一刻不停——真正的恒，恰恰是这种「动而不息」。</p><p>卦辞「亨，无咎，利贞，利有攸往」点明：恒亨通、无咎，但前提是守正（利贞），而且必须往前走（利有攸往）。恒不是静止，是「动得久」。</p><h3 id="理-为什么这一卦重要" tabindex="-1">理：为什么这一卦重要 <a class="header-anchor" href="#理-为什么这一卦重要" aria-label="Permalink to &quot;理：为什么这一卦重要&quot;">​</a></h3><p>恒，不是坚持就是胜利，而是在正确的方向上，知道何时守、何时动、何时止。</p><p>三个维度：</p><ol><li><strong>方向之恒</strong> —— 恒的前提是方向对，方向错了再恒也空（九四田无禽）</li><li><strong>德行之恒</strong> —— 无人看见时你怎么选，人后守恒才是真恒（九三）</li><li><strong>知止之恒</strong> —— 终点是知道何时止，到点收手，恒才有善终（上六）</li></ol><h3 id="用-今天如何应用" tabindex="-1">用：今天如何应用 <a class="header-anchor" href="#用-今天如何应用" aria-label="Permalink to &quot;用：今天如何应用&quot;">​</a></h3><ol><li>先确认方向，再谈坚持——方向错的恒是固执</li><li>恒在点子上，错了立刻回来——「悔亡」靠的是纠错快</li><li>无人看见时，守住你的德——人后恒定，人前才立得住</li><li>到点知止——不把坚持熬成执念，不把恒透支成惯性</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>恒卦的完整地图：</p><table tabindex="0"><thead><tr><th>爻位</th><th>爻辞要点</th><th>功课</th><th>关键词</th></tr></thead><tbody><tr><td>卦辞</td><td>亨，无咎，利贞，利有攸往</td><td>守正而动，动得久</td><td>恒是动得久</td></tr><tr><td>初六</td><td>浚恒，贞凶，无攸利</td><td>根基未稳不求深，先固根</td><td>始求深</td></tr><tr><td>九二</td><td>悔亡</td><td>守恒于中，错而能改</td><td>悔亡三要件</td></tr><tr><td>九三</td><td>不恒其德，或承之羞</td><td>人后守恒，德行不废</td><td>无所容也</td></tr><tr><td>九四</td><td>田无禽</td><td>确认方向，再谈坚持</td><td>久非其位</td></tr><tr><td>六五</td><td>妇人吉，夫子凶</td><td>真守 vs 以守逃避</td><td>制义</td></tr><tr><td>上六</td><td>振恒，凶</td><td>知止，到点收手</td><td>大无功</td></tr></tbody></table><p>核心洞见：</p><ol><li><strong>恒不是坚持就是胜利</strong>——而是方向对了之后的持久</li><li><strong>恒的悖论</strong>——日月四时皆变，却因各循其道而恒</li><li><strong>恒是长出来的，不是挖出来的</strong>——浚恒求深，根必先伤</li><li><strong>悔亡 = 方向对 + 中道 + 纠错快</strong></li><li><strong>人后恒，才是真恒</strong>——无人看见时你怎么选</li><li><strong>方向错的坚持叫固执</strong>——九四田无禽</li><li><strong>恒的终点是知止</strong>——知道何时守、何时动、何时止</li></ol><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><p>恒卦照见的，是郭子仪——信用复利的一生。</p><ul><li><strong>初六 · 浚恒 → 沉潜五十八年</strong>：郭子仪以武举入仕，长期默默无闻，安史之乱爆发时他已五十八岁。别人笑他大器晚成，他不辩解——根没扎够，就不急着冒头。这正是浚恒的反面：不挖，只长。</li><li><strong>九二 · 悔亡 → 收复两京</strong>：方向终于到来——平叛。找对方向的郭子仪一举收复长安、洛阳，悔亡。方向对了，之前所有的沉潜都变成了复利。</li><li><strong>九三 · 不恒其德 → 鱼朝恩掘墓</strong>：功高震主，宦官鱼朝恩掘其父坟。郭子仪不报复、不辩解，只流泪自责「臣久主兵，不能禁暴」。承羞而不失其德——德行之恒，在无人看见、甚至被人伤害时，依然立得住。</li><li><strong>九四 · 田无禽 → 二十骑出发</strong>：回纥来袭，众将劝退，他带着二十骑赴敌营。看似无望的方向，他确认过再出发。方向对了，二十骑也是千军万马；方向错了，千军万马也只是二十骑。</li><li><strong>六五 · 妇人吉夫子凶 → 单骑退回纥</strong>：营帐之前，他卸下甲胄、单骑而前，以诚退敌，不战而屈人之兵。君位之守，不是死守城门，而是制义而行——该退时退，才是真守。</li><li><strong>上六 · 振恒凶 → 府门大开，八十五岁善终</strong>：晚年大开府门、任人出入，自曝于天下，消尽皇帝猜忌。他知道何时收、何时止——功成身退，善终汾阳。</li></ul><p>《旧唐书》评郭子仪：</p><blockquote><p>权倾天下而朝不忌，功盖一代而主不疑。</p></blockquote><p>恒德之极，不过如此。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>相关卦象：咸（第三十一卦）、遁（第三十三卦）</li><li>恒与咸的连结：咸是感应——「感而遂通」；恒是感应之后的持久。无感不成恒，感而不恒只是一阵风。少男少女之咸，到雷风之恒：感情、事业、信念，皆从「感」入、以「恒」成。</li><li>恒与遁的连结：遁是知退——避开锋芒、全身而退；恒是知止——到点收手。能退、能止，恒才有善终。</li><li>相关专题：<a href="/Dao/topics/yin-yang">阴阳</a>、<a href="/Dao/topics/xiang-shu-li">象数理</a></li></ul>',23))])}}});export{x as __pageData,y as default};
